562	fn write_toml(path: &Path, value: &TomlValue) -> Result<()> {
563	    let parent = path
564	        .parent()
565	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
566	        .unwrap_or(Path::new("."));
567	    let serialized = toml::to_string_pretty(value).context("serialising TOML")?;
568	    let mut tmp = tempfile::NamedTempFile::new_in(parent)
569	        .with_context(|| format!("creating temp file in {}", parent.display()))?;
570	    std::io::Write::write_all(&mut tmp, serialized.as_bytes())
571	        .with_context(|| format!("writing temp file for {}", path.display()))?;
572	    tmp.persist(path)
573	        .map_err(|e| anyhow!("atomic rename to {} failed: {}", path.display(), e.error))?;
574	    Ok(())
575	}
