696	fn set_at_path(root: &mut TomlValue, path: &str, value: TomlValue) -> Result<()> {
697	    let parts: Vec<&str> = path.split('.').collect();
698	    let (last, parents) = parts
699	        .split_last()
700	        .ok_or_else(|| anyhow!("empty key path"))?;
701	
702	    let mut cur: &mut TomlValue = root;
703	    for p in parents {
704	        let tbl = cur
705	            .as_table_mut()
706	            .ok_or_else(|| anyhow!("path segment `{}` has a non-table parent", p))?;
707	        cur = tbl
708	            .entry((*p).to_string())
709	            .or_insert_with(|| TomlValue::Table(toml::Table::new()));
710	    }
711	    let tbl = cur
712	        .as_table_mut()
713	        .ok_or_else(|| anyhow!("target parent is not a table"))?;
714	    tbl.insert((*last).to_string(), value);
715	    Ok(())
716	}
