718	fn parse_scalar(input: &str, explicit: Option<ScalarType>) -> Result<TomlValue> {
719	    let ty = explicit.unwrap_or_else(|| infer_type(input));
720	    match ty {
721	        ScalarType::Str => Ok(TomlValue::String(input.to_string())),
722	        ScalarType::Int => Ok(TomlValue::Integer(
723	            input
724	                .parse::<i64>()
725	                .with_context(|| format!("`{}` is not a valid int", input))?,
726	        )),
727	        ScalarType::Float => Ok(TomlValue::Float(
728	            input
729	                .parse::<f64>()
730	                .with_context(|| format!("`{}` is not a valid float", input))?,
731	        )),
732	        ScalarType::Bool => Ok(TomlValue::Boolean(
733	            input
734	                .parse::<bool>()
735	                .with_context(|| format!("`{}` is not a valid bool", input))?,
736	        )),
737	        ScalarType::Date | ScalarType::Datetime => {
738	            let dt: toml::value::Datetime = input
739	                .parse()
740	                .with_context(|| format!("`{}` is not a valid TOML datetime", input))?;
741	            Ok(TomlValue::Datetime(dt))
742	        }
743	    }
