758	fn looks_like_date(s: &str) -> bool {
759	    let b = s.as_bytes();
760	    b.len() == 10
761	        && b[4] == b'-'
762	        && b[7] == b'-'
763	        && b[..4].iter().all(|c| c.is_ascii_digit())
764	        && b[5..7].iter().all(|c| c.is_ascii_digit())
765	        && b[8..10].iter().all(|c| c.is_ascii_digit())
766	}
