888	/// Strict `a > b` comparison for TOML Datetime values. Compares the string
889	/// representations, which is correct for ISO-8601 dates and date-times — the
890	/// lexicographic order on ISO-8601 matches chronological order.
891	fn datetime_gt(a: &toml::value::Datetime, b: &toml::value::Datetime) -> bool {
892	    a.to_string() > b.to_string()
893	}
