1054	fn items_next_id(doc: &TomlValue, prefix: &str) -> Result<String> {
1055	    if prefix.is_empty() {
1056	        bail!("prefix must not be empty — use a letter like R, O, or A");
1057	    }
1058	    if prefix.chars().all(|c| c.is_ascii_digit()) {
1059	        bail!("prefix must not be all-digit — would collide with numeric-suffix parsing");
1060	    }
1061	    let mut max_n: u64 = 0;
1062	    if let Ok(arr) = items_array(doc) {
1063	        for item in arr {
1064	            if let Some(id) = item_id(item)
1065	                && let Some(rest) = id.strip_prefix(prefix)
1066	                && let Ok(n) = rest.parse::<u64>()
1067	                && n > max_n
1068	            {
1069	                max_n = n;
1070	            }
1071	        }
1072	    }
1073	    Ok(format!("{}{}", prefix, max_n + 1))
1074	}
