1271	fn items_orphans(doc: &TomlValue) -> Result<Vec<JsonValue>> {
1272	    let items = match items_array(doc) {
1273	        Ok(a) => a,
1274	        Err(_) => return Ok(Vec::new()),
1275	    };
1276	
1277	    // Build set of known IDs for dangling-dep check.
1278	    let mut known_ids: HashSet<String> = HashSet::new();
1279	    for item in items {
1280	        if let Some(id) = item_id(item) {
1281	            known_ids.insert(id.to_string());
1282	        }
1283	    }
1284	
1285	    let root = repo_or_cwd_root()?;
1286	
1287	    let mut out = Vec::new();
1288	    for item in items {
1289	        let tbl = match item.as_table() {
1290	            Some(t) => t,
1291	            None => continue,
1292	        };
1293	        let id = tbl.get("id").and_then(|v| v.as_str()).unwrap_or("");
1294	        let file = tbl.get("file").and_then(|v| v.as_str()).unwrap_or("");
1295	        let symbol = tbl.get("symbol").and_then(|v| v.as_str()).unwrap_or("");
1296	
1297	        // missing-file / symbol-missing classes (mutually exclusive: the first
1298	        // failing check wins).
1299	        if !file.is_empty() {
1300	            let resolved = resolve_relative_to_root(&root, file);
1301	            if !resolved.exists() {
1302	                let mut obj = serde_json::Map::new();
1303	                obj.insert("id".into(), JsonValue::String(id.into()));
1304	                obj.insert("class".into(), JsonValue::String("missing-file".into()));
1305	                obj.insert("file".into(), JsonValue::String(file.into()));
1306	                out.push(JsonValue::Object(obj));
1307	            } else if !symbol.is_empty() {
1308	                let contents = fs::read_to_string(&resolved).unwrap_or_default();
1309	                if !contents.contains(symbol) {
1310	                    let mut obj = serde_json::Map::new();
1311	                    obj.insert("id".into(), JsonValue::String(id.into()));
1312	                    obj.insert("class".into(), JsonValue::String("symbol-missing".into()));
1313	                    obj.insert("file".into(), JsonValue::String(file.into()));
1314	                    obj.insert("symbol".into(), JsonValue::String(symbol.into()));
1315	                    out.push(JsonValue::Object(obj));
1316	                }
1317	            }
1318	        }
1319	
1320	        // dangling-dep class (independent of the file/symbol axis; an item can
1321	        // be orphaned in both ways and will surface twice).
1322	        if let Some(deps) = tbl.get("depends_on").and_then(|v| v.as_array()) {
1323	            let mut missing: Vec<String> = Vec::new();
1324	            for dep in deps {
1325	                if let Some(d) = dep.as_str()
1326	                    && !known_ids.contains(d)
1327	                {
1328	                    missing.push(d.to_string());
1329	                }
1330	            }
1331	            if !missing.is_empty() {
1332	                let mut obj = serde_json::Map::new();
1333	                obj.insert("id".into(), JsonValue::String(id.into()));
1334	                obj.insert("class".into(), JsonValue::String("dangling-dep".into()));
1335	                obj.insert(
1336	                    "dangling_deps".into(),
1337	                    JsonValue::Array(missing.into_iter().map(JsonValue::String).collect()),
1338	                );
1339	                out.push(JsonValue::Object(obj));
1340	            }
1341	        }
1342	    }
1343	    Ok(out)
1344	}
