1394	fn scan_block_names(contents: &str) -> Vec<String> {
1395	    let mut names = Vec::new();
1396	    for line in contents.lines() {
1397	        let trimmed = line.trim();
1398	        if let Some(rest) = trimmed.strip_prefix("<!-- SHARED-BLOCK:")
1399	            && let Some(inner) = rest.strip_suffix(" START -->")
1400	        {
1401	            let n = inner.trim().to_string();
1402	            if !names.contains(&n) {
1403	                names.push(n);
1404	            }
1405	        }
1406	    }
1407	    names
1408	}
