1410	fn blocks_verify(files: &[PathBuf], blocks: &[String]) -> Result<BlocksReport> {
1411	    if files.is_empty() {
1412	        bail!("blocks verify: no files supplied");
1413	    }
1414	    // If no block names given, infer from the first file.
1415	    let effective_blocks: Vec<String> = if blocks.is_empty() {
1416	        let first = &files[0];
1417	        let c = fs::read_to_string(first)
1418	            .with_context(|| format!("reading {}", first.display()))?;
1419	        scan_block_names(&c)
1420	    } else {
1421	        blocks.to_vec()
1422	    };
1423	
1424	    // Preload every file once.
1425	    let mut contents_by_file: HashMap<PathBuf, String> = HashMap::new();
1426	    for f in files {
1427	        let c = fs::read_to_string(f)
1428	            .with_context(|| format!("reading {}", f.display()))?;
1429	        contents_by_file.insert(f.clone(), c);
1430	    }
1431	
1432	    let mut all_ok = true;
1433	    let mut blocks_out = Vec::new();
1434	    for name in &effective_blocks {
1435	        let mut per_file: Vec<(PathBuf, Option<String>)> = Vec::new();
1436	        for f in files {
1437	            let contents = &contents_by_file[f];
1438	            match extract_block(contents, name) {
1439	                Some(bytes) => {
1440	                    let digest = hex_lower(&Sha256::digest(&bytes));
1441	                    per_file.push((f.clone(), Some(digest)));
1442	                }
1443	                None => per_file.push((f.clone(), None)),
1444	            }
1445	        }
1446	
1447	        let mut present: Vec<&(PathBuf, Option<String>)> = per_file
1448	            .iter()
1449	            .filter(|(_, h)| h.is_some())
1450	            .collect();
1451	        let missing: Vec<JsonValue> = per_file
1452	            .iter()
1453	            .filter(|(_, h)| h.is_none())
1454	            .map(|(f, _)| JsonValue::String(path_to_string(f)))
1455	            .collect();
1456	
1457	        let mut block_obj = serde_json::Map::new();
1458	        block_obj.insert("name".into(), JsonValue::String(name.clone()));
1459	
1460	        if present.is_empty() {
1461	            all_ok = false;
1462	            block_obj.insert("ok".into(), JsonValue::Bool(false));
1463	            block_obj.insert("missing".into(), JsonValue::Array(missing));
1464	            blocks_out.push(JsonValue::Object(block_obj));
1465	            continue;
1466	        }
1467	
1468	        // Sort present by file path for deterministic output.
1469	        present.sort_by(|a, b| a.0.cmp(&b.0));
1470	        let first_hash = present[0].1.as_ref().unwrap().clone();
1471	        let drift = present
1472	            .iter()
1473	            .any(|(_, h)| h.as_ref().unwrap() != &first_hash);
1474	
1475	        if drift || !missing.is_empty() {
1476	            all_ok = false;
1477	        }
1478	
1479	        if drift {
1480	            block_obj.insert("ok".into(), JsonValue::Bool(false));
1481	            let drift_arr: Vec<JsonValue> = present
1482	                .iter()
1483	                .map(|(f, h)| {
1484	                    let mut o = serde_json::Map::new();
1485	                    o.insert("file".into(), JsonValue::String(path_to_string(f)));
1486	                    o.insert("hash".into(), JsonValue::String(h.clone().unwrap()));
1487	                    JsonValue::Object(o)
1488	                })
1489	                .collect();
1490	            block_obj.insert("drift".into(), JsonValue::Array(drift_arr));
1491	            block_obj.insert("missing".into(), JsonValue::Array(missing));
1492	        } else {
1493	            let files_arr: Vec<JsonValue> = present
1494	                .iter()
1495	                .map(|(f, _)| JsonValue::String(path_to_string(f)))
1496	                .collect();
1497	            block_obj.insert("hash".into(), JsonValue::String(first_hash));
1498	            block_obj.insert("files".into(), JsonValue::Array(files_arr));
1499	            block_obj.insert("missing".into(), JsonValue::Array(missing));
1500	        }
1501	        blocks_out.push(JsonValue::Object(block_obj));
1502	    }
1503	
1504	    let mut top = serde_json::Map::new();
1505	    top.insert("ok".into(), JsonValue::Bool(all_ok));
1506	    top.insert("blocks".into(), JsonValue::Array(blocks_out));
1507	    Ok(BlocksReport {
1508	        ok: all_ok,
1509	        ok_field: JsonValue::Object(top),
1510	    })
1511	}
