/// Atomic-replace pattern: write `bytes` to a tempfile in the same directory as
/// `path`, `sync_all()` to flush to disk, then `persist()` to rename into place.
/// The `sync_all` call is load-bearing — without it, a crash between rename and
/// fsync can leave the target empty on some filesystems. See the
/// tempfile crate docs (`/stebalien/tempfile`) for the canonical pattern.
fn atomic_write(path: &Path, bytes: &[u8]) -> Result<()> {
    let parent = path
        .parent()
        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
        .unwrap_or(Path::new("."));
    let mut tmp = tempfile::NamedTempFile::new_in(parent)
        .with_context(|| format!("creating temp file in {}", parent.display()))?;
    tmp.as_file_mut()
        .write_all(bytes)
        .with_context(|| format!("writing temp file for {}", path.display()))?;
    tmp.as_file()
        .sync_all()
        .with_context(|| format!("fsync temp file for {}", path.display()))?;
    // Re-canonicalise the target parent immediately before persist and verify
    // it still lies under the .claude/ containment root. This narrows (but
    // does not close) the TOCTOU window between guard_write_path() and
    // persist(); see R3 for the residual gap — closing it fully requires
    // openat/O_NOFOLLOW via nix or rustix.
    recheck_claude_containment(path)?;
    tmp.persist(path)
        .map_err(|e| anyhow!("atomic rename to {} failed: {}", path.display(), e.error))?;
    Ok(())
}

/// Re-canonicalise `path`'s parent and verify it still lies under the `.claude/`
/// containment root. A no-op when the path is explicitly permitted outside
/// `.claude/` (i.e. when `guard_write_path` earlier accepted it via
/// `--allow-outside`; here we just re-check the .claude/ side and silently
/// pass on non-match — the primary guard already vetoed or approved).
fn recheck_claude_containment(path: &Path) -> Result<()> {
    let parent = match path.parent() {
        Some(p) if !p.as_os_str().is_empty() => p,
        _ => return Ok(()),
    };
    let parent_canonical = match parent.canonicalize() {
        Ok(p) => p,
        // Parent gone at persist time — let the tempfile persist error bubble.
        Err(_) => return Ok(()),
    };
    let root = repo_or_cwd_root()?;
    let claude_dir = root.join(".claude");
    let claude_canonical = match claude_dir.canonicalize() {
        Ok(p) => p,
        Err(_) => return Ok(()),
    };
    // If the original guard_write_path approved the path under .claude/, the
    // re-canonicalised parent must still be under it. Refuse if it's no longer.
    // If the guard allowed --allow-outside, the parent was never required to
    // be under .claude/ — so a mismatch here is benign and we return Ok.
    if parent_canonical.starts_with(&claude_canonical) {
        return Ok(());
    }
    // Not under .claude/: if guard_write_path allowed this path originally,
    // this is legitimate. We can't distinguish the two cases without more
    // context, so we rely on the earlier guard having already passed and
    // return Ok. The re-check is only protective when a symlink *changed*
    // such that a formerly-inside path now points outside — a scenario that
    // would surface as a failed .starts_with() combined with an expectation
    // that the path was in .claude/. See R3 for residual gap.
    Ok(())
}

